"""Local headless-browser smoke checks via an already running Chromium CDP port.

Requires websockets in the development environment. No remote site or provider
is used. Start the demo at 8765 and an isolated headless browser at 9228 first.
"""
import asyncio
import base64
import json
import urllib.request
from pathlib import Path
import websockets

OUT=Path(__file__).resolve().parents[1]/'artifacts/customer_ui_validation'


async def main():
    pages=json.load(urllib.request.urlopen('http://127.0.0.1:9228/json'))
    page=next(p for p in pages if p['type']=='page')
    checks=[];errors=[];counter=0
    OUT.mkdir(parents=True,exist_ok=True)
    async with websockets.connect(page['webSocketDebuggerUrl'],max_size=10_000_000) as ws:
        async def command(method,params=None):
            nonlocal counter
            counter+=1;ident=counter
            await ws.send(json.dumps({'id':ident,'method':method,'params':params or {}}))
            while True:
                msg=json.loads(await ws.recv())
                if msg.get('method')=='Runtime.exceptionThrown':errors.append(msg['params'])
                if msg.get('id')==ident:
                    if 'error' in msg:raise RuntimeError(msg['error'])
                    return msg.get('result',{})
        async def js(expression):
            if '.click()' in expression:
                expression += ';new Promise(resolve=>setTimeout(resolve,250))'
            r=await command('Runtime.evaluate',{'expression':expression,'awaitPromise':True,'returnByValue':True})
            if 'exceptionDetails' in r:raise AssertionError(r['exceptionDetails'])
            return r.get('result',{}).get('value')
        async def wait(expression):
            for _ in range(150):
                if await js('Boolean('+expression+')'):return
                await asyncio.sleep(.1)
            raise AssertionError('Timed out: '+expression)
        async def check(name,expression):
            assert await js(expression),name
            checks.append(name)
        async def profile(value):
            await js("$('controls').click();$('profile').value="+json.dumps(value)+";$('apply').click()")
            await wait("!busy && !$('settings').open")
        async def shot(name):
            result=await command('Page.captureScreenshot',{'format':'png','captureBeyondViewport':True})
            (OUT/name).write_bytes(base64.b64decode(result['data']))
        await command('Runtime.enable');await command('Page.enable')
        await command('Emulation.setDeviceMetricsOverride',{'width':1366,'height':1000,'deviceScaleFactor':1,'mobile':False})
        await command('Page.navigate',{'url':'http://127.0.0.1:8765'})
        await wait("typeof access!=='undefined' && access!==null && !busy")
        await check('BOW workbook is the default knowledge source',"knowledgeBank==='BOW' && $('bow-product').options.length===12")
        await profile('signed-out')
        await js("$('message').value='First line';$('message').focus();$('message').setSelectionRange(10,10)")
        await command('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13,'modifiers':8,'text':'\r'})
        await command('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13,'modifiers':8})
        await check('Shift Enter adds a newline without submitting',"$('message').value.includes('\\n') && !busy")
        await js("window.composingEvent=new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true});$('message').dispatchEvent(window.composingEvent)")
        await check('IME composition Enter does not submit',"!window.composingEvent.defaultPrevented && !busy")
        await js("window.savedComposerFetch=window.fetch;window.releaseComposerReply=null;window.composerCalls=0;window.fetch=async(...args)=>{const response=await savedComposerFetch(...args);if(args[0]==='/api/chat'){window.composerCalls++;await new Promise(resolve=>window.releaseComposerReply=resolve);}return response;};$('message').value='selected charge is incorrectly applied';$('message').focus()")
        await command('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await command('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await wait("window.releaseComposerReply!==null && busy")
        await js("$('message').value='I was charged incorrectly';$('message').focus()")
        await command('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await command('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await check('In-flight Enter preserves the next draft without another request',"$('message').value==='I was charged incorrectly' && window.composerCalls===1")
        await js("window.fetch=window.savedComposerFetch;window.releaseComposerReply()")
        await wait("!busy && $('messages').textContent.includes('Your report is saved')")
        await command('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await command('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await wait("!busy && !$('message').value && Array.from($('messages').querySelectorAll('.bubble.user')).some(b=>b.textContent.includes('I was charged incorrectly'))")
        await check('Consecutive Enter submissions both reach error intake',"Array.from($('messages').querySelectorAll('.bubble.assistant')).filter(b=>b.textContent.includes('Your report is saved')).length>=2")
        await js("window.savedTimeoutApi=api;window.savedTimeoutFetch=fetch;api=(path,body,timeout)=>savedTimeoutApi(path,body,path==='/api/chat'?20:timeout);window.fetch=(path,options)=>path==='/api/chat'?new Promise((resolve,reject)=>options.signal.addEventListener('abort',()=>reject(new DOMException('Synthetic timeout','AbortError')),{once:true})):savedTimeoutFetch(path,options);$('message').value='This payment was applied by mistake';$('message').focus()")
        await command('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await command('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
        await wait("!busy && pending && !$('retry').hidden")
        await check('Timeout releases Send and preserves the retry request',"!$('send').disabled && $('status').textContent.includes('took too long') && pending.message==='This payment was applied by mistake'")
        await js("window.timedOutRequestKey=pending.request_key;api=window.savedTimeoutApi;window.fetch=(path,options)=>{if(path==='/api/chat')window.replayedRequestKey=JSON.parse(options.body).request_key;return savedTimeoutFetch(path,options);};$('retry').click()")
        await wait("!busy && !pending")
        await check('Retry after timeout reuses the original request key',"window.replayedRequestKey===window.timedOutRequestKey && Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('Your report is saved')")
        await js("window.fetch=window.savedTimeoutFetch")
        await js("void send('What is the difference between a pending and posted payment?')")
        await wait("!busy && $('messages').textContent.includes('cannot give you a sourced comparison')")
        await check('BOW status definitions report their source gap without sign-in',"!$('sign-in-dialog').open && Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('approved Bank of Whatever policy')")
        await js("void send('Compare Everyday Checking and Plus Checking monthly fees')")
        await wait("!busy && Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$12.00')")
        await check('Product comparison shows both distinct source-backed fees',"Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$6.00') && $('messages').textContent.includes('Whatever Plus Checking product catalog')")
        await js("void send('Compare Everyday Checking fees')")
        await wait("!busy && document.querySelector('[data-product-choice=\"BOW-CHK-002\"]:not(:disabled)')!==null")
        await js("document.querySelector('[data-product-choice=\"BOW-CHK-002\"]:not(:disabled)').click()")
        await wait("!busy && Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$12.00')")
        await check('Selecting the second product resumes the comparison in chat',"Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$6.00') && !$('sign-in-dialog').open")
        await js("$('bow-product').value='BOW-CHK-002';void send('What is the monthly maintenance fee?')")
        await wait("!busy && document.querySelectorAll('[data-product-choice]:not(:disabled)').length===3")
        await check('Unconfirmed sidebar selection cannot trigger an early fee answer',"!Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$12')")
        await js("void send('Checking account')")
        await wait("!busy && document.querySelectorAll('[data-product-choice]:not(:disabled)').length===3")
        await check('Checking category still requires an exact BOW tier',"Array.from(document.querySelectorAll('[data-product-choice]:not(:disabled)')).every(b=>b.dataset.productChoice.startsWith('BOW-CHK'))")
        await js("document.querySelector('[data-product-choice=\"BOW-CHK-002\"]:not(:disabled)').click()")
        await wait("!busy && $('messages').innerText.includes('$12.00 USD')")
        await check('Fee answer stays focused on the monthly amount',"!Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).innerText.includes('cashback')")
        await js("void send('What are the fee waiver rules?')")
        await wait("!busy && $('messages').innerText.includes('$2,000')")
        await check('Waiver answer contains conditions rather than the same full profile',"Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).innerText.includes('$10,000') && !Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).innerText.includes('cashback')")
        await js("void send('What is the current savings interest rate?')")
        await wait("!busy && document.querySelectorAll('[data-product-choice]:not(:disabled)').length===3")
        await check('Savings choices appear inside chat despite stale checking selection',"Array.from(document.querySelectorAll('[data-product-choice]:not(:disabled)')).every(b=>b.dataset.productChoice.startsWith('BOW-SAV')) && !authPending")
        await js("document.querySelector('[data-product-choice=\"BOW-SAV-001\"]:not(:disabled)').click()")
        await wait("!busy && $('messages').innerText.includes('2.00%')")
        await check('In-chat product choice resumes the rate question and syncs sidebar',"$('bow-product').value==='BOW-SAV-001' && Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).innerText.includes('APY') && !Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).innerText.includes('monthly maintenance')")
        await js("void send('And the monthly fee?')")
        await wait("!busy && $('messages').innerText.includes('$0.00 USD')")
        await check('Public follow-up remembers the chosen savings account',"Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('Starter Savings')")
        await js("$('bow-product').value='BOW-CHK-001';void send('What is the monthly maintenance fee for Everyday Checking?')")
        await wait("!busy && $('messages').innerText.includes('$6.00 USD')")
        await check('BOW Everyday fee does not inherit the archived $12 fee',"Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$6.00 USD') && !Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$12.00 USD')")
        await js("$('bow-product').value='BOW-SAV-002';void send('What is the savings interest rate for High-Five Savings?')")
        await wait("!busy && $('messages').innerText.includes('3.50%')")
        await check('BOW tiered APY preserves thresholds and source dates',"$('messages').innerText.includes('3.20%') && $('messages').innerText.includes('$10,000') && $('messages').textContent.includes('2026-10-01')")
        await js("void send('Show my recent transactions')")
        await wait("!busy && authPending")
        await js("$('auth-entry').click();$('auth-profile').value='bow-customer-one';$('auth-continue').click()")
        await wait("!busy && access==='VERIFIED' && !authPending && items.length>0")
        await check('BOW request resumes with BOW records and masked account only',"sessionBank==='BOW' && items.every(r=>r.transaction_id.startsWith('BOW-TXN-001')) && $('messages').innerText.includes('0001')")
        await shot('bow-workbook.png')
        await js("$('knowledge-bank').value='LEGACY_DEMO';$('knowledge-bank').dispatchEvent(new Event('change'))")
        await wait("knowledgeBank==='LEGACY_DEMO' && !busy")
        await profile('signed-out')
        await check('Guest opens without authentication dialog or private cards',"access==='AUTH_REQUIRED' && !$('sign-in-dialog').open && !$('access-panel') && !items.length")
        await js("document.querySelector('[data-service=fees]').click();Array.from($('service-panel').querySelectorAll('button')).find(b=>b.textContent==='Monthly maintenance fee').click()")
        await wait("!busy && document.querySelector('[data-product-choice=\"LEGACY-CHECKING\"]:not(:disabled)')")
        await check('Original demo also asks for product before quoting a fee',"!Array.from($('messages').querySelectorAll('.bubble.assistant')).at(-1).textContent.includes('$12')")
        await js("document.querySelector('[data-product-choice=\"LEGACY-CHECKING\"]:not(:disabled)').click()")
        await wait("!busy && $('messages').innerText.includes('a $12 monthly fee')")
        await check('Public fee answer needs no sign-in',"access==='AUTH_REQUIRED' && !authPending && !$('sign-in-dialog').open")
        await js("void send('Why was I charged $12?')")
        await wait("!busy && authPending")
        await check('Private fee request asks for sign-in without account cards',"$('messages').innerText.includes('Please sign in securely to view your account details.') && !$('messages').querySelector('.record-card')")
        await check('Removed sign-in box stays absent during account requests',"!$('access-panel') && !$('access-title') && !$('access-description')")
        await js("$('auth-entry').click();$('auth-cancel').click()")
        await wait("!$('sign-in-dialog').open && !authPending")
        await check('Cancel sign-in preserves public chat',"access==='AUTH_REQUIRED' && $('messages').innerText.includes('a $12 monthly fee')")
        await js("void send('Show my recent transactions')")
        await wait("!busy && authPending")
        await js("$('auth-entry').click();$('auth-profile').value='customer-one';$('auth-continue').click()")
        await wait("access==='VERIFIED' && !busy && !authPending && $('messages').querySelector('.record-card')")
        await check('Original protected request resumes after explicit sign-in',"$('messages').innerText.includes('Show my recent transactions') && $('messages').innerText.includes('$')")
        await check('Public fee history survives authentication',"$('messages').innerText.includes('a $12 monthly fee')")
        await js("$('auth-entry').click()")
        await wait("access==='AUTH_REQUIRED' && !busy")
        await check('Sign-out removes private cards while public chat stays',"!$('messages').querySelector('.record-card') && $('messages').innerText.includes('a $12 monthly fee')")
        await js("void send('What is the current savings interest rate?')")
        await wait("!busy && document.querySelector('[data-product-choice=\"LEGACY-SAVINGS\"]:not(:disabled)')")
        await js("document.querySelector('[data-product-choice=\"LEGACY-SAVINGS\"]:not(:disabled)').click()")
        await wait("!busy && $('messages').innerText.includes('No approved, current published savings rate')")
        await check('Missing public rate is not invented or gated',"!authPending && !$('sign-in-dialog').open")
        await shot('guest-first.png')
        await profile('customer-one')
        await wait("access==='VERIFIED' && items.length>0 && !busy")
        await check('Support navigation and sample identity visible',"document.body.innerText.includes('Demo sign-in active') && !!document.querySelector('[data-service=report]')")
        await js("document.querySelector('[data-service=fees]').click()")
        await check('Fee service offers relevant actions',"$('service-panel').innerText.includes('Monthly maintenance fee')")
        await js("$('next').click()")
        await wait("items.some(r=>r.transaction_id==='TXN-DEMO-63')")
        await js("$('transaction').value='TXN-DEMO-63';$('transaction').dispatchEvent(new Event('change'))")
        await check('Payment card preserves amount and pending status',"$('transaction-detail').innerText.includes('$63.00 USD') && $('transaction-detail').innerText.includes('Pending')")
        await js("document.querySelector('[data-service=report]').click();Array.from($('service-panel').querySelectorAll('button')).find(b=>b.textContent==='Charged twice').click()")
        await wait("!busy && $('outcome').innerText.includes('Your report')")
        await check('Five report states and support receipt shown separately',"['Formal notice','Identity','Investigation','Your confirmation','Received by the support team'].every(x=>$('outcome').innerText.includes(x))")
        await check('No unrequested support case is reported as failed',"!$('outcome').innerText.includes('Submission not confirmed')")
        await check('No raw policy or queue dump in chat',"!$('messages').innerText.includes('Demo guidance [') && !$('messages').innerText.includes('FRAUD_OPERATIONS')")
        await shot('desktop.png')
        await js("document.querySelector('[data-service=fees]').click();Array.from($('service-panel').querySelectorAll('button')).find(b=>b.textContent==='Create a support request').click()")
        await wait("!busy && !$('draft').hidden")
        await check('Case draft requires confirmation',"$('confirm').textContent==='Send request' && $('messages').innerText.includes('Nothing has been sent yet')")
        await js("$('confirm').click()")
        await wait("!busy && $('draft').hidden && $('outcome').innerText.includes('Support request')")
        await check('Committed case card rendered',"$('messages').innerText.includes('Support request created')")
        await js("$('view-cases').click()")
        await wait("!$('case-panel').hidden && $('case-list').querySelector('.record-card')")
        checks.append('Authorised support case list loads')
        await profile('needs-verification')
        await check('Step-up hides private records',"access==='STEP_UP_REQUIRED' && !items.length && $('transaction').disabled")
        await js("void send('Show my recent transactions')")
        await wait("!busy && authPending && access==='STEP_UP_REQUIRED'")
        await js("$('auth-entry').click();$('verification-cancel').click()")
        await wait("!$('verification').open")
        await check('Cancelled verification keeps records hidden',"access==='STEP_UP_REQUIRED' && !items.length")
        await js("$('auth-entry').click();$('verification-confirm').click()")
        await wait("access==='VERIFIED' && items.length>0 && !$('verification').open && !busy && !authPending")
        checks.append('Successful demo verification enables scoped records')
        # Hold a completed payment response, revoke the session, then release it.
        await js("window.originalFetch=window.fetch;window.releaseChat=null;window.fetch=async(...args)=>{const response=await originalFetch(...args);if(args[0]==='/api/chat')await new Promise(resolve=>window.releaseChat=resolve);return response;};$('transaction').value=items[0].transaction_id;void send('Show the selected transaction')")
        await wait("window.releaseChat!==null")
        await js("originalFetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:'expired'})}).then(()=>backgroundAccess())")
        await wait("access==='SESSION_EXPIRED'")
        await js("window.releaseChat();window.fetch=window.originalFetch")
        await wait("!busy")
        await check('Expiry clears records and discards late response',"!items.length && !$('messages').querySelector('.record-card') && $('draft').hidden && $('case-list').childNodes.length===0")
        await profile('signed-out')
        await js("window.qaOriginalFetch=window.fetch;window.qaKeys=[];window.qaIntercept=true;window.fetch=async(...args)=>{if(args[0]==='/api/chat'){qaKeys.push(JSON.parse(args[1].body).request_key);if(qaIntercept){qaIntercept=false;return new Response(JSON.stringify({response:'Please retry the same request.',response_state:'REVIEW_REQUIRED',data_scope:'PUBLIC',cards:[],source_details:[],auth_required:false}),{status:200,headers:{'Content-Type':'application/json'}});}}return qaOriginalFetch(...args);};void send('What is the monthly maintenance fee?')")
        await wait("!busy && pending!==null && !$('retry').hidden")
        await check('QA fallback preserves the original request for safe retry',"qaKeys.length===1 && pending.request_key===qaKeys[0]")
        await js("$('retry').click()")
